[TestClass][DoNotParallelize]public sealed class PlanningCanvasConsistencyTests
{
 internal static string Root{get{var p=Environment.GetEnvironmentVariable("KITAO_PLANNING_CANVAS_ROOT")??throw new InvalidOperationException("Explicit isolated test root required");Directory.CreateDirectory(p);return p;}}
 internal static BitmapSource Decode(string png){using var f=new MemoryStream(Convert.FromBase64String(png));var b=BitmapDecoder.Create(f,BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnLoad).Frames[0];b.Freeze();return b;}
 internal static byte[] Pixels(BitmapSource b){var x=new FormatConvertedBitmap(b,PixelFormats.Bgra32,null,0);var bytes=new byte[x.PixelWidth*x.PixelHeight*4];x.CopyPixels(bytes,x.PixelWidth*4,0);return bytes;}
 internal static async Task<CanvasDocument> Mixed(Guid? project=null,string? canvasRoot=null){EnsureTestApplication();var root=Path.Combine(Root,"inputs");Directory.CreateDirectory(root);var document=new CanvasDocument{SchemaVersion=2,PixelWidth=420,PixelHeight=300,ProjectId=project};var data=new byte[48*36*4];for(int y=0;y<36;y++)for(int x=0;x<48;x++){var i=(y*48+x)*4;data[i]=(byte)(x*5);data[i+1]=(byte)(y*7);data[i+2]=(byte)(255-x*4);data[i+3]=(byte)(x<5?0:60+(x*3+y)%195);}var image=BitmapSource.Create(48,36,96,96,PixelFormats.Bgra32,null,data,48*4);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));var path=Path.Combine(root,"authorized-owned-alpha.png");using(var f=File.Create(path))encoder.Save(f);var imported=await CanvasPixelRenderer.ImportAsync(path,document,canvasRoot??Path.Combine(Root,"canvas-store"));var first=imported with{X=15,Y=25,Width=180,Height=135,ZIndex=1};var second=first with{ObjectId=Guid.NewGuid(),X=220,Y=150,Width=160,Height=110,Rotation=31,FlipX=true,FlipY=true,CropRect=new(.15,.2,.7,.65),Opacity=.43,ZIndex=3};return document with{Objects=[first,second,new(){CanvasId=document.CanvasId,SourcePath=Path.Combine(root,"offline-hidden.png"),Hidden=true,X=0,Y=0,Width=400,Height=290,ZIndex=8},new(){CanvasId=document.CanvasId,SourceWidth=420,SourceHeight=300,Width=420,Height=300,ZIndex=2,BrushStrokes=[new([new(.1,.65),new(.6,.3),new(.8,.8)],"#7AC345",42,.65,.32)]},new(){CanvasId=document.CanvasId,X=195,Y=12,Width=190,Height=70,Text="固定版本 Canvas",FontSize=22,TextColor="#E78345",Opacity=.67,Rotation=-5,ZIndex=5},new(){CanvasId=document.CanvasId,X=-20,Y=255,Width=200,Height=75,Palette=new([new("#FF0000",0,1,.5,1),new("#00FF00",120,1,.5,3),new("#0000FF",240,1,.5,2)],[]),ZIndex=6}]};}
 [TestMethod]public Task SameDocumentSnapshotMatchesExistingExportIncludingHiddenOfflineAndBrush()=>RunSta(async()=>{
  var doc=await Mixed();var export=Path.Combine(Root,"mixed-export-"+Guid.NewGuid().ToString("N")+".png");CanvasPixelRenderer.ExportPng(doc,export);var expected=Decode(Convert.ToBase64String(File.ReadAllBytes(export)));string? error=null;BitmapSource? snapshot=null;try{snapshot=Decode(PlanningCanvasSnapshot.Render(doc));}catch(Exception e){error=e.GetType().Name+": "+e.Message;}var withoutHidden=doc with{Objects=doc.Objects.Where(o=>!o.Hidden).ToArray()};var old=Decode(PlanningCanvasSnapshot.Render(withoutHidden));File.WriteAllText(Path.Combine(Root,"REPRODUCTION.json"),JsonSerializer.Serialize(new{expectedWidth=doc.PixelWidth,expectedHeight=doc.PixelHeight,snapshotWidth=snapshot?.PixelWidth,snapshotHeight=snapshot?.PixelHeight,hiddenOfflineError=error,withoutHiddenWidth=old.PixelWidth,withoutHiddenHeight=old.PixelHeight,expectedPixels=Convert.ToHexString(SHA256.HashData(Pixels(expected))),snapshotPixels=Convert.ToHexString(SHA256.HashData(Pixels(old)))},new JsonSerializerOptions{WriteIndented=true}));Assert.IsNull(error,"Hidden offline source must never be opened");Assert.AreEqual(doc.PixelWidth,snapshot!.PixelWidth);Assert.AreEqual(doc.PixelHeight,snapshot.PixelHeight);CollectionAssert.AreEqual(Pixels(expected),Pixels(snapshot));
 });
 [TestMethod]public Task PreviewBudgetArtboardRatioAndLegacyExportAreExplicit()=>RunSta(async()=>{
  var doc=await Mixed();var visible=doc with{Objects=doc.Objects.Where(o=>!o.Hidden).ToArray()};var small=CanvasPixelRenderer.RenderPreview(visible,140);Assert.AreEqual(140,small.PixelWidth);Assert.AreEqual(100,small.PixelHeight);var alpha=Pixels(small).Where((_,i)=>i%4==3).ToArray();Assert.IsTrue(alpha.Any(v=>v==0));Assert.IsTrue(alpha.Any(v=>v>0&&v<255));var large=new CanvasDocument{PixelWidth=16000,PixelHeight=4000};var bounded=CanvasPixelRenderer.RenderPreview(large);Assert.AreEqual(1400,bounded.PixelWidth);Assert.AreEqual(350,bounded.PixelHeight);Assert.IsTrue(Pixels(bounded).All(v=>v==0));var hugeBrush=large with{SchemaVersion=2,Objects=[new(){CanvasId=large.CanvasId,SourceWidth=16000,SourceHeight=4000,Width=16000,Height=4000,BrushStrokes=[]}]};Assert.ThrowsExactly<InvalidDataException>(()=>CanvasPixelRenderer.RenderPreview(hugeBrush));using var canceled=new CancellationTokenSource();canceled.Cancel();Assert.ThrowsExactly<OperationCanceledException>(()=>CanvasPixelRenderer.RenderPreview(visible,token:canceled.Token));Assert.ThrowsExactly<InvalidDataException>(()=>CanvasPixelRenderer.RenderPreview(visible,budget:new(MaxWorkingBytes:100)));Assert.ThrowsExactly<InvalidDataException>(()=>CanvasPixelRenderer.RenderPreview(visible,budget:new(MaxLayers:1)));
  var output=Path.Combine(Root,"mixed-small.png");var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(small));using(var f=File.Create(output))e.Save(f);await File.WriteAllTextAsync(Path.Combine(Root,"BUDGET.json"),JsonSerializer.Serialize(new{artboard=new[]{16000,4000},preview=new[]{bounded.PixelWidth,bounded.PixelHeight},floatOutputBytes=bounded.PixelWidth*bounded.PixelHeight*16,neverAllocatedFullArtboardFloat=true,maxWorkingBytes=256L*1024*1024,maxLayers=1000,timeoutSeconds=20,contract=PlanningCanvasSnapshot.SamplingContract}));
 });
 [TestMethod]public Task CaptureSavesBeforePublishAndManualUpdateKeepsOldVersion()=>RunSta(async()=>{
  using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);var canvas=await Mixed(f.Id,Path.Combine(f.Root,"canvas"));var store=new CanvasDocumentStore(Path.Combine(f.Root,"canvas"));await store.SaveAsync(canvas);await f.Vm.LoadAsync(f.Id);await f.Vm.CaptureCanvasDocumentAsync(canvas);var first=f.Vm.DocumentCanvasRevisions.Single();Assert.AreEqual(2,first.RenderVersion);Assert.AreEqual(420,first.PreviewWidth);Assert.AreEqual(300,first.PreviewHeight);var persisted=(await f.Planning.LoadAsync(f.Id)).Document!.Package!.CanvasRevisions.Single();Assert.AreEqual(first.PreviewPngBase64,persisted.PreviewPngBase64);Assert.IsTrue(await f.Vm.FlushAsync());var other=f.NewVm();await other.LoadAsync(f.Id);Assert.AreEqual(first.PreviewPngBase64,other.DocumentCanvasRevisions.Single().PreviewPngBase64);
  var changed=canvas with{Objects=canvas.Objects.Select(i=>i.IsText?i with{Text="手动更新的新版本"}:i).ToArray()};await store.SaveAsync(changed);Assert.AreEqual(first.PreviewPngBase64,other.DocumentCanvasRevisions.Single().PreviewPngBase64,"Saved fixed preview never recomputes on canvas edits");await other.CaptureCanvasDocumentAsync(changed);Assert.AreEqual(2,other.DocumentCanvasRevisions.Count);Assert.AreEqual(first.PreviewPngBase64,other.DocumentCanvasRevisions[0].PreviewPngBase64);Assert.AreNotEqual(first.PreviewPngBase64,other.DocumentCanvasRevisions[1].PreviewPngBase64);Assert.IsTrue(await other.FlushAsync());var third=f.NewVm();await third.LoadAsync(f.Id);Assert.AreEqual(2,third.DocumentCanvasRevisions.Count);var old=new RAWSelectionAssistant.Core.Services.Projects.PlanningCanvasRevision(Guid.NewGuid(),canvas.CanvasId,DateTimeOffset.UnixEpoch,canvas,first.PreviewPngBase64);var legacy=JsonSerializer.Deserialize<RAWSelectionAssistant.Core.Services.Projects.PlanningCanvasRevision>(JsonSerializer.Serialize(old))!;Assert.AreEqual(1,legacy.Validate().RenderVersion);Assert.AreEqual(first.PreviewPngBase64,legacy.PreviewPngBase64);Assert.ThrowsExactly<InvalidDataException>(()=>(first with{RenderVersion=999}).Validate());
 });
 [TestMethod]public Task CancelLateGenerationAndProjectSwitchCannotPublish()=>RunSta(async()=>{
  using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);var canvas=await Mixed(f.Id,Path.Combine(f.Root,"canvas"));var store=new CanvasDocumentStore(Path.Combine(f.Root,"canvas"));await store.SaveAsync(canvas);await f.Vm.CaptureCanvasDocumentAsync(canvas);var old=f.Vm.DocumentCanvasRevisions.Single();var delayed=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);f.Vm.CanvasSnapshotRenderer=(_,t)=>{started.TrySetResult();return delayed.Task;};var work=f.Vm.CaptureCanvasDocumentAsync(canvas);await started.Task;f.Vm.CancelCanvasCapture();delayed.SetResult(old.PreviewPngBase64!);await Assert.ThrowsExactlyAsync<OperationCanceledException>(()=>work);Assert.AreEqual(1,f.Vm.DocumentCanvasRevisions.Count);
  var late=new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);started=new(TaskCreationOptions.RunContinuationsAsynchronously);f.Vm.CanvasSnapshotRenderer=(_,_)=>{started.TrySetResult();return late.Task;};var second=f.Vm.CaptureCanvasDocumentAsync(canvas);await started.Task;var another=Guid.NewGuid();await f.Projects.UpsertAsync(new RAWSelectionAssistant.Core.Models.PhotoProjectRecord{Id=another,Name="另一项目"});await f.Vm.LoadAsync(another);late.SetResult(old.PreviewPngBase64!);await Assert.ThrowsExactlyAsync<OperationCanceledException>(()=>second);Assert.AreEqual(another,f.Vm.ProjectId);Assert.AreEqual(0,f.Vm.DocumentCanvasRevisions.Count);Assert.AreEqual(1,(await f.Planning.LoadAsync(f.Id)).Document!.Package!.CanvasRevisions.Count);Assert.IsTrue(await f.Vm.FlushAsync());
 });
 [TestMethod]public Task MissingTamperedAndSaveFailureKeepPriorVersionAndFile()=>RunSta(async()=>{
  using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);var canvas=await Mixed(f.Id,Path.Combine(f.Root,"canvas"));var store=new CanvasDocumentStore(Path.Combine(f.Root,"canvas"));await store.SaveAsync(canvas);await f.Vm.CaptureCanvasDocumentAsync(canvas);var old=f.Vm.DocumentCanvasRevisions.Single();var target=Path.Combine(f.Planning.StorageRoot,$"{f.Id:N}.planning.json");var prior=File.ReadAllBytes(target);var owned=RAWSelectionAssistant.Core.Services.Projects.PlanningProjectCopyStorage.Resolve(canvas.Objects.First(o=>o.IsImage&&!o.Hidden).PlanningSource!.Bind());var bytes=File.ReadAllBytes(owned);File.WriteAllBytes(owned,bytes.Concat(new byte[]{13}).ToArray());await Assert.ThrowsExactlyAsync<InvalidDataException>(()=>f.Vm.CaptureCanvasDocumentAsync(canvas));Assert.AreEqual(1,f.Vm.DocumentCanvasRevisions.Count);CollectionAssert.AreEqual(prior,File.ReadAllBytes(target));File.WriteAllBytes(owned,bytes);File.Move(owned,owned+".keep");try{await Assert.ThrowsExactlyAsync<FileNotFoundException>(()=>f.Vm.CaptureCanvasDocumentAsync(canvas));}finally{File.Move(owned+".keep",owned);}Assert.AreEqual(old.PreviewPngBase64,f.Vm.DocumentCanvasRevisions.Single().PreviewPngBase64);
  var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var resume=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);f.Vm.CanvasBeforeCommit=async _=>{entered.TrySetResult();await resume.Task;};var work=f.Vm.CaptureCanvasDocumentAsync(canvas);await entered.Task;using(var locked=new FileStream(target,FileMode.Open,FileAccess.Read,FileShare.Read)){resume.SetResult();try{await work;Assert.Fail("Locked destination must reject atomic append");}catch(Exception error)when(error is IOException or UnauthorizedAccessException){}}Assert.AreEqual(1,f.Vm.DocumentCanvasRevisions.Count);Assert.AreEqual(old.PreviewPngBase64,f.Vm.DocumentCanvasRevisions.Single().PreviewPngBase64);CollectionAssert.AreEqual(prior,File.ReadAllBytes(target));Assert.IsFalse(File.Exists(f.Planning.DraftPath(f.Id)),"Uncommitted snapshot must not become a recovery draft");Assert.IsFalse(f.Vm.IsCanvasCaptureRunning);
 });

