 [TestMethod]public Task HistoricalExportFixtureUsesOnlyExistingApis()=>RunSta(async()=>{var doc=await Mixed();var path=Path.Combine(Root,"historical-mixed.png");CanvasPixelRenderer.ExportPng(doc,path);var bytes=Pixels(Decode(Convert.ToBase64String(File.ReadAllBytes(path))));await File.WriteAllTextAsync(Path.Combine(Root,"HISTORICAL_EXPORT.json"),JsonSerializer.Serialize(new{width=doc.PixelWidth,height=doc.PixelHeight,pixelHash=Convert.ToHexString(SHA256.HashData(bytes)),containerHash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)))}));});

 [TestMethod]public Task SnapshotCancellationAndLargeArtboardWorkingSetAreBounded()=>RunSta(async()=>{
  EnsureTestApplication();var clock=System.Diagnostics.Stopwatch.StartNew();using var process=System.Diagnostics.Process.GetCurrentProcess();var before=process.WorkingSet64;var large=new CanvasDocument{PixelWidth=16000,PixelHeight=4000};var png=await PlanningCanvasSnapshot.RenderAsync(large);var elapsed=clock.Elapsed.TotalMilliseconds;var bitmap=Decode(png);Assert.AreEqual(1400,bitmap.PixelWidth);Assert.AreEqual(350,bitmap.PixelHeight);process.Refresh();var after=process.WorkingSet64;var active=large with{Objects=Enumerable.Range(0,100).Select(n=>new CanvasObject{CanvasId=large.CanvasId,Width=1000,Height=1000,X=n*20,Y=0,Palette=new([new("#FF0000",0,1,.5,1),new("#00FF00",120,1,.5,1),new("#0000FF",240,1,.5,1)],[])}).ToArray()};using var cancellation=new CancellationTokenSource();clock.Restart();var work=PlanningCanvasSnapshot.RenderAsync(active,cancellation.Token);await Task.Delay(15);cancellation.Cancel();await Assert.ThrowsAsync<OperationCanceledException>(()=>work);var retirement=clock.Elapsed.TotalMilliseconds;File.WriteAllText(Path.Combine(Root,"PREVIEW_RESOURCE_MEASUREMENT.json"),JsonSerializer.Serialize(new{largeArtboard=new[]{16000,4000},output=new[]{1400,350},workingSetBefore=before,workingSetAfter=after,previewMs=elapsed,cancelRetirementMs=retirement,outputFloatBytes=1400*350*16,fullArtboardFloatBytesNotAllocated=16000L*4000*16,scope="process WS snapshots, not precise allocator peak; WIC native call cancellation not preemptive"},new JsonSerializerOptions{WriteIndented=true}));
 });

 [TestMethod]public Task ViewportNonImageContentRetainsFullObjectCoordinateBounds()=>RunSta(async()=>{
  var doc=await Mixed();var rows=new List<object>();foreach(var item in doc.Objects.Where(i=>!i.IsImage)){var visual=new DrawingVisual();using(var dc=visual.RenderOpen())CanvasPixelRenderer.DrawCanvasContent(dc,item,null);var display=new RenderTargetBitmap(doc.PixelWidth,doc.PixelHeight,96,96,PixelFormats.Pbgra32);display.Render(visual);var single=doc with{Objects=[item]};var reference=CanvasPixelRenderer.RenderPreview(single);var actual=Pixels(display);var expected=Pixels(reference);var alphaA=actual.Where((_,i)=>i%4==3).ToArray();var alphaB=expected.Where((_,i)=>i%4==3).ToArray();double centerA=0,centerB=0,sumA=0,sumB=0;for(int i=0;i<alphaA.Length;i++){centerA+=alphaA[i]*(i/doc.PixelWidth);centerB+=alphaB[i]*(i/doc.PixelWidth);sumA+=alphaA[i];sumB+=alphaB[i];}Assert.AreEqual(centerB/sumB,centerA/sumA,1,"Viewport must not stretch ink bounds to fill object rect");rows.Add(new{kind=item.IsBrush?"brush":item.IsText?"text":"palette",displayAlphaCenterY=centerA/sumA,referenceAlphaCenterY=centerB/sumB});}File.WriteAllText(Path.Combine(Root,"VIEWPORT_BOUNDS.json"),JsonSerializer.Serialize(rows));
 });

}
